# 4.3 — dấu hiệu can thiệp: 1102 (xoá Security), 104 (xoá log khác), 4719 (đổi audit policy), 4616 (đổi giờ), 7040 (tắt dịch vụ Event Log) — mẫu EVTX-to-MITRE-Attack + DeepBlueCLI.
@ps evtx-rec tc/clear-104-1102.evtx | ConvertFrom-Json | Group-Object kenh,id | Select-Object Count,Name | Format-Table -AutoSize
@ps evtx-rec tc/clear-104-1102.evtx | ConvertFrom-Json | Select-Object -First 3 | ForEach-Object { [pscustomobject]@{ Luc = $_.t.ToString('s'); Kenh = $_.kenh; Id = $_.id; Rec = $_.rec; Ai = '{0}\{1}' -f $_.data.SubjectDomainName, $_.data.SubjectUserName; LogBiXoa = $_.data.Channel } } | Format-Table -AutoSize
@ps $e = evtx-rec tc/clear-104-1102.evtx | ConvertFrom-Json | Where-Object id -eq 104; '{0} sự kiện 104: lần 1 lúc {1}; {2} lần còn lại từ {3} tới {4}' -f $e.Count, $e[0].t.ToString('HH:mm:ss'), ($e.Count - 1), $e[1].t.ToString('HH:mm:ss'), $e[-1].t.ToString('HH:mm:ss'); ($e | Group-Object { $_.data.SubjectUserName }).Name
@ps evtx-rec tc/clear-4688-native.evtx | ConvertFrom-Json | Where-Object { $_.data.NewProcessName -like '*wevtutil.exe' } | ForEach-Object { '{0}  {1,-8} {2}' -f $_.t.ToString('HH:mm:ss.fff'), $_.data.SubjectUserName, ($_.data.CommandLine -replace '"C:\\Windows\\system32\\wevtutil.exe"\s+','wevtutil ') }
@ps evtx-rec tc/dung-eventlog.evtx | ConvertFrom-Json | Where-Object id -in 104,7040 | ForEach-Object { '{0}  {1,-5} {2}' -f $_.t.ToString('HH:mm:ss'), $_.id, $(if ($_.id -eq 7040) { '{0}: {1} -> {2}' -f $_.data.param1, $_.data.param2, $_.data.param3 } else { 'xoá log ' + $_.data.Channel + ' bởi ' + $_.data.SubjectUserName }) }
@ps $g = @{}; Get-Content /lab/s04/guid-auditpol.tsv | Where-Object { $_ -notmatch '^#' } | ForEach-Object { $k, $v = $_ -split "`t"; $g[$k] = $v }; evtx-rec tc/audit-4719.evtx | ConvertFrom-Json | Select-Object -First 12 | ForEach-Object { '{0}  {1,-28} {2}' -f $_.t.ToString('HH:mm:ss'), $g[$_.data.SubcategoryGuid.Trim('{}').Substring(0,8)], $_.data.AuditPolicyChanges }
@ps $e = evtx-rec tc/audit-4719.evtx | ConvertFrom-Json; '{0} nhóm con bị đổi trong {1} giây, bởi {2}' -f $e.Count, ($e[-1].t - $e[0].t).TotalSeconds, (($e.data.SubjectUserName | Sort-Object -Unique) -join ',')
@ps evtx-rec mau/dbc-many-events-security.evtx | ConvertFrom-Json | Where-Object id -eq 4719 | Select-Object -First 3 | ForEach-Object { '{0}  {1}  {2}  {3}' -f $_.t.ToString('s'), $_.data.SubjectUserName, $_.data.SubcategoryGuid, $_.data.AuditPolicyChanges }
@ps evtx-rec tc/time-4616.evtx | ConvertFrom-Json | Where-Object id -eq 4616 | ForEach-Object { [pscustomobject]@{ Ai = $_.data.SubjectUserName; Truoc = ([datetime]$_.data.PreviousTime).ToString('MM-dd HH:mm:ss'); Sau = ([datetime]$_.data.NewTime).ToString('MM-dd HH:mm:ss'); Lech_giay = [math]::Round((([datetime]$_.data.NewTime) - ([datetime]$_.data.PreviousTime)).TotalSeconds, 1); Tien_trinh = ($_.data.ProcessName -split '\\')[-1] } } | Format-Table -AutoSize
@ps evtx-rec mau/security.evtx | ConvertFrom-Json | Where-Object id -eq 4616 | ForEach-Object { [math]::Round((([datetime]$_.data.NewTime) - ([datetime]$_.data.PreviousTime)).TotalSeconds) } | Group-Object { if ([math]::Abs($_) -lt 5) { 'lệch < 5 giây' } else { 'lệch ' + $_ + ' giây' } } | Select-Object Count,Name | Format-Table -AutoSize
